                "Cannot delete exercise referenced in performed sets",
                "Conflict",
            )

        ex.is_deleted = True
        try:
            db.commit()
        except Exception:
            db.rollback()
            raise AppException(status.HTTP_500_INTERNAL_SERVER_ERROR, "Database write failure")

